------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [invoice].[latest_revision]
------------------------------------------------------------
IF OBJECT_ID('[stripe].[fninvoicelatest_revision_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [stripe].[fninvoicelatest_revision_GetRootID];
GO

CREATE FUNCTION [stripe].[fninvoicelatest_revision_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [id],
            [latest_revision],
            [id] AS [RootParentID],
            0 AS [Depth]
        FROM
            [stripe].[invoice]
        WHERE
            [id] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[id],
            c.[latest_revision],
            c.[id] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [stripe].[invoice] c
        INNER JOIN
            CTE_RootParent p ON c.[id] = p.[latest_revision]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [latest_revision] IS NULL
    ORDER BY
        [RootParentID]
);
GO

