CREATE TRIGGER [stripe].trgUpdatepayment_method
ON [stripe].[payment_method]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE
        [stripe].[payment_method]
    SET
        __mj_UpdatedAt = GETUTCDATE()
    FROM
        [stripe].[payment_method] AS _organicTable
    INNER JOIN
        INSERTED AS I ON
        _organicTable.[id] = I.[id];
END;
